// Lingua Tungga runtime, inlined into every generated package.
// Regenerated by `lt build`; do not edit by hand.

export type Unit = null;

export interface Displayable {
  readonly __lt_meta: VariantMeta;
}

// Ordering and display of a variant, shared by every value of that variant so
// the payload itself stays pure data.
export type VariantMeta = {
  readonly order: number;
  readonly display: (value: any) => string;
};

export type Opt<T> =
  | { readonly tag: "some"; readonly values: readonly [T]; readonly __lt_meta: VariantMeta }
  | { readonly tag: "none"; readonly values: readonly []; readonly __lt_meta: VariantMeta };

export type Res<T, E> =
  | { readonly tag: "ok"; readonly values: readonly [T]; readonly __lt_meta: VariantMeta }
  | { readonly tag: "err"; readonly values: readonly [E]; readonly __lt_meta: VariantMeta };

export function print(value: unknown): void {
  console.log(disp(value));
}

export function disp(value: unknown): string {
  if (typeof value === "bigint") return value.toString();
  if (typeof value === "string") return value;
  if (typeof value === "number") {
    return Number.isInteger(value) ? value.toFixed(1) : String(value);
  }
  if (typeof value === "boolean") return value ? "true" : "false";
  if (value === null || value === undefined) return "None";
  const object = value as any;
  if (object.__lt_meta !== undefined && typeof object.__lt_meta.display === "function") {
    return object.__lt_meta.display(value);
  }
  if (typeof object.__lt_to_string === "function") return object.__lt_to_string();
  if (typeof object.toString === "function" && object.toString !== Object.prototype.toString) {
    return object.toString();
  }
  return JSON.stringify(value);
}

export function eq(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  const left = a as any;
  const right = b as any;
  if (left === null || right === null || left === undefined || right === undefined) return false;
  if (typeof left === "bigint" || typeof right === "bigint") return left === right;
  if (typeof left !== "object" || typeof right !== "object") return left === right;
  if (typeof left.__lt_eq === "function") return left.__lt_eq(right);
  if (Array.isArray(left) && Array.isArray(right)) {
    if (left.length !== right.length) return false;
    return left.every((item: unknown, index: number) => eq(item, right[index]));
  }
  if ("tag" in left && "tag" in right) {
    return left.tag === right.tag && eq(left.values, right.values);
  }
  return false;
}

export function cmp(a: unknown, b: unknown): number {
  const leftValue = a as any;
  if (leftValue !== null && typeof leftValue === "object") {
    if (typeof leftValue.__lt_cmp === "function") return leftValue.__lt_cmp(b);
    const rightValue = b as any;
    if (
      leftValue.__lt_meta !== undefined &&
      typeof leftValue.__lt_meta.order === "number" &&
      rightValue !== null &&
      typeof rightValue === "object" &&
      rightValue.__lt_meta !== undefined &&
      typeof rightValue.__lt_meta.order === "number"
    ) {
      if (leftValue.__lt_meta.order !== rightValue.__lt_meta.order) {
        return leftValue.__lt_meta.order < rightValue.__lt_meta.order ? -1 : 1;
      }
      const leftItems = leftValue.values ?? [];
      const rightItems = rightValue.values ?? [];
      for (let index = 0; index < Math.min(leftItems.length, rightItems.length); index += 1) {
        const step = cmp(leftItems[index], rightItems[index]);
        if (step !== 0) return step;
      }
      return leftItems.length - rightItems.length;
    }
  }
  if (typeof a === "bigint" && typeof b === "bigint") return a < b ? -1 : a > b ? 1 : 0;
  if (typeof a === "number" && typeof b === "number") return a < b ? -1 : a > b ? 1 : 0;
  if (typeof a === "string" && typeof b === "string") return a < b ? -1 : a > b ? 1 : 0;
  if (typeof a === "boolean" && typeof b === "boolean") return Number(a) - Number(b);
  const left = disp(a);
  const right = disp(b);
  return left < right ? -1 : left > right ? 1 : 0;
}

/// Lexicographic comparison, so collections have a total order of their own
/// instead of falling back to display strings in `cmp`.
function compareItems(left: readonly unknown[], right: readonly unknown[]): number {
  const limit = Math.min(left.length, right.length);
  for (let index = 0; index < limit; index += 1) {
    const step = cmp(left[index], right[index]);
    if (step !== 0) return step;
  }
  return left.length - right.length;
}

function compareEntries(
  left: readonly (readonly [unknown, unknown])[],
  right: readonly (readonly [unknown, unknown])[],
): number {
  const limit = Math.min(left.length, right.length);
  for (let index = 0; index < limit; index += 1) {
    const key = cmp(left[index][0], right[index][0]);
    if (key !== 0) return key;
    const value = cmp(left[index][1], right[index][1]);
    if (value !== 0) return value;
  }
  return left.length - right.length;
}

// --- Int: i64 with wrapping overflow ---------------------------------------
export const iadd = (a: bigint, b: bigint): bigint => BigInt.asIntN(64, a + b);
export const isub = (a: bigint, b: bigint): bigint => BigInt.asIntN(64, a - b);
export const imul = (a: bigint, b: bigint): bigint => BigInt.asIntN(64, a * b);
export const idiv = (a: bigint, b: bigint): bigint => BigInt.asIntN(64, a / b);
export const irem = (a: bigint, b: bigint): bigint => BigInt.asIntN(64, a % b);
export const ineg = (a: bigint): bigint => BigInt.asIntN(64, -a);

// --- Option ----------------------------------------------------------------
const noneDisplay = (value: any): string =>
  value.tag === "none" ? "None" : `Some(${disp(value.values[0])})`;
const noneMeta: VariantMeta = { order: 0, display: noneDisplay };
const someMeta: VariantMeta = { order: 1, display: noneDisplay };

const noneValue: Opt<never> = {
  tag: "none",
  values: [],
  __lt_meta: noneMeta,
};

export function Some<T>(value: T): Opt<T> {
  return { tag: "some", values: [value], __lt_meta: someMeta };
}

export function None<T>(): Opt<T> {
  return noneValue as Opt<T>;
}

export const optIsSome = <T>(value: Opt<T>): boolean => value.tag === "some";
export const optIsNone = <T>(value: Opt<T>): boolean => value.tag === "none";

export function optUnwrap<T>(value: Opt<T>): T {
  if (value.tag === "none") throw new Error("unwrap on None");
  return value.values[0];
}

export function optUnwrapOr<T>(value: Opt<T>, fallback: T): T {
  return value.tag === "some" ? value.values[0] : fallback;
}

export function optMap<T, U>(value: Opt<T>, f: (value: T) => U): Opt<U> {
  return value.tag === "some" ? Some(f(value.values[0])) : None<U>();
}

export function optAndThen<T, U>(value: Opt<T>, f: (value: T) => Opt<U>): Opt<U> {
  return value.tag === "some" ? f(value.values[0]) : None<U>();
}

// --- Result ----------------------------------------------------------------
const resDisplay = (value: any): string =>
  value.tag === "ok" ? `Ok(${disp(value.values[0])})` : `Err(${disp(value.values[0])})`;

const resMeta: VariantMeta = { order: 0, display: resDisplay };
const errMeta: VariantMeta = { order: 1, display: resDisplay };

export function Ok<T, E>(value: T): Res<T, E> {
  return { tag: "ok", values: [value], __lt_meta: resMeta };
}

export function Err<T, E>(value: E): Res<T, E> {
  return { tag: "err", values: [value], __lt_meta: errMeta };
}

export const resIsOk = <T, E>(value: Res<T, E>): boolean => value.tag === "ok";
export const resIsErr = <T, E>(value: Res<T, E>): boolean => value.tag === "err";

export function resUnwrap<T, E>(value: Res<T, E>): T {
  if (value.tag === "err") throw new Error(`unwrap on Err(${disp(value.values[0])})`);
  return value.values[0];
}

export function resUnwrapOr<T, E>(value: Res<T, E>, fallback: T): T {
  return value.tag === "ok" ? value.values[0] : fallback;
}

export function resMap<T, U, E>(value: Res<T, E>, f: (value: T) => U): Res<U, E> {
  return value.tag === "ok" ? Ok<U, E>(f(value.values[0])) : Err<U, E>(value.values[0]);
}

export function resMapErr<T, E, F>(value: Res<T, E>, f: (value: E) => F): Res<T, F> {
  return value.tag === "ok" ? Ok<T, F>(value.values[0]) : Err<T, F>(f(value.values[0]));
}

export function resAndThen<T, U, E>(value: Res<T, E>, f: (value: T) => Res<U, E>): Res<U, E> {
  return value.tag === "ok" ? f(value.values[0]) : Err<U, E>(value.values[0]);
}

// --- Str helpers (indexing is by Unicode code point) -----------------------
export const strLen = (value: string): bigint => BigInt([...value].length);

export function strSlice(value: string, start: bigint, end: bigint): string {
  return [...value].slice(Number(start), Number(end)).join("");
}

export const strChars = (value: string): LList<string> => new LList([...value]);

export function strTrimIndent(value: string): string {
  const lines = value.replace(/^\n/, "").replace(/\n[ \t]*$/, "").split("\n");
  const indents = lines
    .filter((line) => line.trim().length > 0)
    .map((line) => line.match(/^[ \t]*/)?.[0].length ?? 0);
  const common = indents.length === 0 ? 0 : Math.min(...indents);
  return lines.map((line) => line.slice(common)).join("\n");
}

export function strParseInt(value: string): Opt<bigint> {
  const trimmed = value.trim();
  if (!/^[+-]?\d+$/.test(trimmed)) return None<bigint>();
  try {
    return Some(BigInt(trimmed));
  } catch {
    return None<bigint>();
  }
}

export function strParseFloat(value: string): Opt<number> {
  const trimmed = value.trim();
  if (trimmed === "") return None<number>();
  const parsed = Number(trimmed);
  return Number.isNaN(parsed) ? None<number>() : Some(parsed);
}

export const strSplit = (value: string, separator: string): LList<string> =>
  new LList(value.split(separator));

export const strReplace = (value: string, from: string, to: string): string =>
  from === "" ? value : value.split(from).join(to);

// --- Immutable collections -------------------------------------------------
export class LList<T> {
  readonly items: readonly T[];

  constructor(items: readonly T[]) {
    this.items = items;
  }

  len(): bigint {
    return BigInt(this.items.length);
  }

  get(index: bigint): Opt<T> {
    const position = Number(index);
    if (position < 0 || position >= this.items.length) return None<T>();
    return Some(this.items[position]);
  }

  push(value: T): LList<T> {
    return new LList([...this.items, value]);
  }

  pop(): Opt<T> {
    return this.items.length === 0 ? None<T>() : Some(this.items[this.items.length - 1]);
  }

  map<U>(f: (value: T) => U): LList<U> {
    return new LList(this.items.map(f));
  }

  filter(f: (value: T) => boolean): LList<T> {
    return new LList(this.items.filter(f));
  }

  fold<A>(init: A, f: (accumulator: A, value: T) => A): A {
    let result = init;
    for (const item of this.items) result = f(result, item);
    return result;
  }

  any(f: (value: T) => boolean): boolean {
    return this.items.some(f);
  }

  all(f: (value: T) => boolean): boolean {
    return this.items.every(f);
  }

  sort(): LList<T> {
    return new LList([...this.items].sort(cmp));
  }

  reverse(): LList<T> {
    return new LList([...this.items].reverse());
  }

  concat(other: LList<T>): LList<T> {
    return new LList([...this.items, ...other.items]);
  }

  contains(value: T): boolean {
    return this.items.some((item) => eq(item, value));
  }

  index_of(value: T): Opt<bigint> {
    const index = this.items.findIndex((item) => eq(item, value));
    return index < 0 ? None<bigint>() : Some(BigInt(index));
  }

  join(separator: string): string {
    return this.items.map(disp).join(separator);
  }

  __lt_eq(other: unknown): boolean {
    return other instanceof LList && eq(this.items, other.items);
  }

  __lt_cmp(other: unknown): number {
    return other instanceof LList ? compareItems(this.items, other.items) : 0;
  }

  __lt_to_string(): string {
    return `List(${this.items.map(disp).join(", ")})`;
  }
}

export class LSet<T> {
  readonly items: readonly T[];

  constructor(items: readonly T[]) {
    const unique: T[] = [];
    for (const item of items) {
      if (!unique.some((existing) => eq(existing, item))) unique.push(item);
    }
    this.items = unique.sort(cmp);
  }

  len(): bigint {
    return BigInt(this.items.length);
  }

  insert(value: T): LSet<T> {
    return new LSet([...this.items, value]);
  }

  remove(value: T): LSet<T> {
    return new LSet(this.items.filter((item) => !eq(item, value)));
  }

  contains(value: T): boolean {
    return this.items.some((item) => eq(item, value));
  }

  union(other: LSet<T>): LSet<T> {
    return new LSet([...this.items, ...other.items]);
  }

  intersect(other: LSet<T>): LSet<T> {
    return new LSet(this.items.filter((item) => other.contains(item)));
  }

  difference(other: LSet<T>): LSet<T> {
    return new LSet(this.items.filter((item) => !other.contains(item)));
  }

  __lt_eq(other: unknown): boolean {
    return other instanceof LSet && eq(this.items, other.items);
  }

  __lt_cmp(other: unknown): number {
    return other instanceof LSet ? compareItems(this.items, other.items) : 0;
  }

  __lt_to_string(): string {
    return `Set(${this.items.map(disp).join(", ")})`;
  }
}

export class LMap<K, V> {
  readonly entries: readonly (readonly [K, V])[];

  constructor(entries: readonly (readonly [K, V])[]) {
    const sorted = [...entries].sort((left, right) => cmp(left[0], right[0]));
    // Sorted keys make equal keys adjacent, so one pass replaces the old O(n²)
    // scan. The later entry wins, which keeps `insert` last-wins.
    const unique: (readonly [K, V])[] = [];
    for (const entry of sorted) {
      const last = unique[unique.length - 1];
      if (last !== undefined && eq(last[0], entry[0])) unique[unique.length - 1] = entry;
      else unique.push(entry);
    }
    this.entries = unique;
  }

  static empty<K, V>(): LMap<K, V> {
    return new LMap<K, V>([]);
  }

  len(): bigint {
    return BigInt(this.entries.length);
  }

  /// Entries are sorted by key, so lookup is a binary search.
  private slot(key: K): number {
    let low = 0;
    let high = this.entries.length - 1;
    while (low <= high) {
      const middle = (low + high) >> 1;
      const step = cmp(this.entries[middle][0], key);
      if (step === 0) return middle;
      if (step < 0) low = middle + 1;
      else high = middle - 1;
    }
    return -1;
  }

  get(key: K): Opt<V> {
    // `cmp` is total for ordinary keys; verify with `eq` so a pathological key
    // (NaN) falls back to the old linear behaviour instead of guessing.
    const slot = this.slot(key);
    if (slot >= 0 && eq(this.entries[slot][0], key)) return Some(this.entries[slot][1]);
    const entry = this.entries.find((candidate) => eq(candidate[0], key));
    return entry === undefined ? None<V>() : Some(entry[1]);
  }

  insert(key: K, value: V): LMap<K, V> {
    return new LMap([...this.entries, [key, value] as const]);
  }

  remove(key: K): LMap<K, V> {
    return new LMap(this.entries.filter((entry) => !eq(entry[0], key)));
  }

  keys(): LList<K> {
    return new LList(this.entries.map((entry) => entry[0]));
  }

  values(): LList<V> {
    return new LList(this.entries.map((entry) => entry[1]));
  }

  contains_key(key: K): boolean {
    const slot = this.slot(key);
    if (slot >= 0 && eq(this.entries[slot][0], key)) return true;
    return this.entries.some((entry) => eq(entry[0], key));
  }

  __lt_eq(other: unknown): boolean {
    return other instanceof LMap && eq(this.entries, other.entries);
  }

  __lt_cmp(other: unknown): number {
    return other instanceof LMap ? compareEntries(this.entries, other.entries) : 0;
  }

  __lt_to_string(): string {
    return `Map(${this.entries.map((entry) => `${disp(entry[0])}: ${disp(entry[1])}`).join(", ")})`;
  }
}


/// String-keyed, insertion-ordered map. `Eq` ignores order; `cmp` is canonical
/// (entries compared by key) so equal dicts always compare equal.
export class LDict<V> {
  readonly entries: readonly (readonly [string, V])[];
  private readonly index: Map<string, V>;

  constructor(entries: readonly (readonly [string, V])[]) {
    const ordered: (readonly [string, V])[] = [];
    const positions = new Map<string, number>();
    for (const [key, value] of entries) {
      const position = positions.get(key);
      if (position === undefined) {
        positions.set(key, ordered.length);
        ordered.push([key, value]);
      } else {
        // Updating a key keeps its original position, like a Python dict.
        ordered[position] = [key, value];
      }
    }
    this.entries = ordered;
    this.index = new Map(ordered.map(([key, value]) => [key, value] as const));
  }

  static empty<V>(): LDict<V> {
    return new LDict<V>([]);
  }

  len(): bigint {
    return BigInt(this.entries.length);
  }

  get(key: string): Opt<V> {
    return this.index.has(key) ? Some(this.index.get(key) as V) : None<V>();
  }

  insert(key: string, value: V): LDict<V> {
    return new LDict([...this.entries, [key, value] as const]);
  }

  remove(key: string): LDict<V> {
    return new LDict(this.entries.filter(([candidate]) => candidate !== key));
  }

  keys(): LList<string> {
    return new LList(this.entries.map(([key]) => key));
  }

  values(): LList<V> {
    return new LList(this.entries.map(([, value]) => value));
  }

  contains_key(key: string): boolean {
    return this.index.has(key);
  }

  __lt_eq(other: unknown): boolean {
    if (!(other instanceof LDict) || other.entries.length !== this.entries.length) return false;
    return this.entries.every(([key, value]) => {
      if (!other.index.has(key)) return false;
      return eq(value, other.index.get(key) as V);
    });
  }

  __lt_cmp(other: unknown): number {
    if (!(other instanceof LDict)) return 0;
    const byKey = (left: readonly [string, V], right: readonly [string, V]): number =>
      left[0] < right[0] ? -1 : left[0] > right[0] ? 1 : 0;
    return compareEntries([...this.entries].sort(byKey), [...other.entries].sort(byKey));
  }

  __lt_to_string(): string {
    return `Dict(${this.entries.map(([key, value]) => `${key}: ${disp(value)}`).join(", ")})`;
  }
}

// --- JSON -------------------------------------------------------------------
// The reader builds the caller's `Value` directly through the constructor set,
// so the runtime never needs to know that type. Numbers stay exact: an integral
// literal becomes a bigint and everything else a float.
export type ValueFactory<T> = {
  Null: T;
  Bool: (value: boolean) => T;
  Int: (value: bigint) => T;
  Float: (value: number) => T;
  Str: (value: string) => T;
  Array: (items: LList<T>) => T;
  Object: (entries: LDict<T>) => T;
};

class JsonReader<T> {
  private position = 0;

  constructor(
    private readonly text: string,
    private readonly make: ValueFactory<T>,
  ) {}

  parse(): T {
    const value = this.value();
    this.space();
    if (this.position !== this.text.length) this.fail("trailing characters");
    return value;
  }

  private fail(message: string): never {
    throw new Error(`${message} at offset ${this.position}`);
  }

  private space(): void {
    while (this.position < this.text.length) {
      const ch = this.text[this.position];
      if (ch !== " " && ch !== "\t" && ch !== "\n" && ch !== "\r") return;
      this.position += 1;
    }
  }

  private take(): string {
    const ch = this.text[this.position];
    if (ch === undefined) this.fail("unexpected end of input");
    this.position += 1;
    return ch;
  }

  private expect(ch: string): void {
    if (this.take() !== ch) this.fail(`expected \`${ch}\``);
  }

  private value(depth = 0): T {
    if (depth > 128) this.fail("nesting is too deep");
    this.space();
    const ch = this.text[this.position];
    if (ch === undefined) this.fail("unexpected end of input");
    if (ch === "{") return this.object(depth);
    if (ch === "[") return this.array(depth);
    if (ch === '"') return this.make.Str(this.string());
    if (ch === "-" || (ch >= "0" && ch <= "9")) return this.number();
    if (this.text.startsWith("true", this.position)) {
      this.position += 4;
      return this.make.Bool(true);
    }
    if (this.text.startsWith("false", this.position)) {
      this.position += 5;
      return this.make.Bool(false);
    }
    if (this.text.startsWith("null", this.position)) {
      this.position += 4;
      return this.make.Null;
    }
    this.fail("expected a value");
  }

  private object(depth: number): T {
    this.expect("{");
    const entries: [string, T][] = [];
    this.space();
    if (this.text[this.position] === "}") {
      this.position += 1;
      return this.make.Object(new LDict(entries));
    }
    for (;;) {
      this.space();
      if (this.text[this.position] !== '"') this.fail("expected a key");
      const key = this.string();
      this.space();
      this.expect(":");
      entries.push([key, this.value(depth + 1)]);
      this.space();
      const ch = this.take();
      if (ch === "}") return this.make.Object(new LDict(entries));
      if (ch !== ",") this.fail("expected `,` or `}`");
    }
  }

  private array(depth: number): T {
    this.expect("[");
    const items: T[] = [];
    this.space();
    if (this.text[this.position] === "]") {
      this.position += 1;
      return this.make.Array(new LList(items));
    }
    for (;;) {
      items.push(this.value(depth + 1));
      this.space();
      const ch = this.take();
      if (ch === "]") return this.make.Array(new LList(items));
      if (ch !== ",") this.fail("expected `,` or `]`");
    }
  }

  private number(): T {
    const start = this.position;
    if (this.text[this.position] === "-") this.position += 1;
    while (this.position < this.text.length && /[0-9]/.test(this.text[this.position])) {
      this.position += 1;
    }
    let integral = true;
    if (this.text[this.position] === ".") {
      integral = false;
      this.position += 1;
      while (this.position < this.text.length && /[0-9]/.test(this.text[this.position])) {
        this.position += 1;
      }
    }
    if (this.text[this.position] === "e" || this.text[this.position] === "E") {
      integral = false;
      this.position += 1;
      if (this.text[this.position] === "+" || this.text[this.position] === "-") this.position += 1;
      while (this.position < this.text.length && /[0-9]/.test(this.text[this.position])) {
        this.position += 1;
      }
    }
    const raw = this.text.slice(start, this.position);
    if (!/^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$/.test(raw)) {
      this.position = start;
      this.fail("invalid number");
    }
    if (integral) {
      try {
        return this.make.Int(BigInt(raw));
      } catch {
        return this.make.Float(Number(raw));
      }
    }
    return this.make.Float(Number(raw));
  }

  private string(): string {
    this.expect('"');
    let out = "";
    for (;;) {
      const ch = this.take();
      if (ch === '"') return out;
      if (ch !== "\\") {
        if (ch < " ") this.fail("control character in a string");
        out += ch;
        continue;
      }
      const escape = this.take();
      switch (escape) {
        case '"': out += '"'; break;
        case "\\": out += "\\"; break;
        case "/": out += "/"; break;
        case "b": out += "\b"; break;
        case "f": out += "\f"; break;
        case "n": out += "\n"; break;
        case "r": out += "\r"; break;
        case "t": out += "\t"; break;
        case "u": {
          const hex = this.text.slice(this.position, this.position + 4);
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) this.fail("invalid escape");
          this.position += 4;
          out += String.fromCharCode(parseInt(hex, 16));
          break;
        }
        default:
          this.fail("invalid escape");
      }
    }
  }
}

export function jsonParse<T>(text: string, make: ValueFactory<T>): Res<T, string> {
  try {
    return Ok<T, string>(new JsonReader<T>(text, make).parse());
  } catch (error) {
    return Err<T, string>(error instanceof Error ? error.message : String(error));
  }
}

function jsonQuote(text: string): string {
  return JSON.stringify(text);
}

export function jsonStringify(value: unknown): string {
  const tagged = value as any;
  switch (tagged.tag) {
    case "Null":
      return "null";
    case "Bool":
      return tagged.values[0] ? "true" : "false";
    case "Int":
      return (tagged.values[0] as bigint).toString();
    case "Float": {
      const number = tagged.values[0] as number;
      if (!Number.isFinite(number)) return "null";
      return Number.isInteger(number) ? number.toFixed(1) : String(number);
    }
    case "Str":
      return jsonQuote(tagged.values[0] as string);
    case "Array": {
      const items = (tagged.values[0] as LList<unknown>).items;
      return `[${items.map(jsonStringify).join(",")}]`;
    }
    case "Object": {
      const entries = (tagged.values[0] as LDict<unknown>).entries;
      return `{${entries
        .map(([key, item]) => `${jsonQuote(key)}:${jsonStringify(item)}`)
        .join(",")}}`;
    }
    default:
      throw new Error(`json.stringify needs a Value, found ${String(tagged.tag)}`);
  }
}

// --- Test assertions -------------------------------------------------------
export function expectEqual(actual: unknown, expected: unknown): void {
  if (!eq(actual, expected)) {
    throw new Error(`assertion failed: expected ${disp(expected)}, got ${disp(actual)}`);
  }
}

export function expectNotEqual(actual: unknown, expected: unknown): void {
  if (eq(actual, expected)) {
    throw new Error(`assertion failed: expected ${disp(actual)} to differ from ${disp(expected)}`);
  }
}

export function expectTrue(value: boolean): void {
  if (!value) throw new Error("assertion failed: expected true");
}

export function expectFalse(value: boolean): void {
  if (value) throw new Error("assertion failed: expected false");
}
